// Zapytanie od gościa z oficjalnej strony Pensjonatu Grań (ul. Kolorowa 3, Karpacz)
const payload = items[0].json.body || items[0].json;

const roomPrices = {
  dwuosobowy: 160,
  trzyosobowy: 220,
  studio_rodzinne: 300
};

const roomType = payload.roomType || 'dwuosobowy';
const pricePerNight = roomPrices[roomType] || 160;
const nights = payload.nights || 2;
const estimatedTotal = pricePerNight * nights;

// Odpowiedzi FAQ specyficzne dla Pensjonatu Grań (z analizy Deep Research)
const skiLiftInfo = "Stok Pohulanka i wyciągi Kolorowa znajdują się zaledwie 100 metrów od pensjonatu!";
const parkingInfo = "Bezpłatne miejsca publiczne na ul. Kolorowej lub prywatny zamykany parking 20m dalej (15 zł/dobę).";
const mealsInfo = "W cenie pobytu oferujemy przepyszne śniadania w formie szwedzkiego bufetu i obiadokolacje.";

return [
  {
    json: {
      status: "success",
      hotel: "Pensjonat Grań przy ul. Kolorowej 3 w Karpaczu",
      guestName: payload.name || "Gość",
      email: payload.email || "",
      phone: payload.phone || "",
      roomType: roomType,
      nights: nights,
      pricePerNight: pricePerNight,
      estimatedTotal: estimatedTotal,
      otaCommissionSaved18Pct: (estimatedTotal * 0.18).toFixed(2),
      faqSkiLift: skiLiftInfo,
      faqParking: parkingInfo,
      faqMeals: mealsInfo,
      aiResponseMessage: `Dzień dobry! Potwierdzamy dostępność pokoju na ${nights} noce w Pensjonacie Grań. Koszt całkowity bez prowizji: ${estimatedTotal} zł. ${skiLiftInfo} ${parkingInfo}`
    }
  }
];
